import{_ as e,c as i,o as l,ah as o}from"./chunks/framework.l36K22_3.js";const t="/assets/page1.xhYdi_xL.png",f=JSON.parse('{"title":"HTTP 缓存机制","description":"","frontmatter":{},"headers":[],"relativePath":"tiku/network/page1.md","filePath":"tiku/network/page1.md","lastUpdated":1730685270000}'),r={name:"tiku/network/page1.md"};function h(n,a,c,d,s,u){return l(),i("div",null,a[0]||(a[0]=[o('<h1 id="http-缓存机制" tabindex="-1">HTTP 缓存机制 <a class="header-anchor" href="#http-缓存机制" aria-label="Permalink to &quot;HTTP 缓存机制&quot;">​</a></h1><h2 id="相关问题" tabindex="-1">相关问题 <a class="header-anchor" href="#相关问题" aria-label="Permalink to &quot;相关问题&quot;">​</a></h2><ul><li>了解浏览器的缓存机制吗</li><li>谈谈 HTTP 缓存</li><li>为什么要有缓存</li><li>缓存的优点是什么</li></ul><h2 id="回答关键点" tabindex="-1">回答关键点 <a class="header-anchor" href="#回答关键点" aria-label="Permalink to &quot;回答关键点&quot;">​</a></h2><p><code>强缓存</code> <code>协商缓存</code></p><p>HTTP 缓存主要分为<strong>强缓存</strong>和<strong>协商缓存</strong>。</p><p><strong>强缓存</strong>可以通过 Expires / Cache-Control 控制，命中强缓存时不会发起网络请求，资源直接从本地获取，浏览器显示状态码 200 from cache。</p><p><strong>协商缓存</strong>可以通过 Last-Modified / If-Modified-Since 和 Etag / If-None-Match 控制，开启协商缓存时向服务器发送的请求会带上缓存标识，若命中协商缓存服务器返回 304 Not Modified 表示浏览器可以使用本地缓存文件，否则返回 200 OK 正常返回数据。</p><h2 id="知识点深入" tabindex="-1">知识点深入 <a class="header-anchor" href="#知识点深入" aria-label="Permalink to &quot;知识点深入&quot;">​</a></h2><h3 id="_1-流程图" tabindex="-1">1. 流程图 <a class="header-anchor" href="#_1-流程图" aria-label="Permalink to &quot;1. 流程图&quot;">​</a></h3><p><img src="'+t+'" alt="" loading="lazy"></p><h3 id="_2-强缓存" tabindex="-1">2. 强缓存 <a class="header-anchor" href="#_2-强缓存" aria-label="Permalink to &quot;2. 强缓存&quot;">​</a></h3><h4 id="_2-1-expires" tabindex="-1">2.1 Expires <a class="header-anchor" href="#_2-1-expires" aria-label="Permalink to &quot;2.1 Expires&quot;">​</a></h4><ul><li>HTTP/1.0 产物。</li><li>优先级低于 Cache-control: max-age。</li><li>缺点：使用本地时间判断是否过期，而本地时间是可修改的且并非一定准确的。</li></ul><p>Expires 是由服务端返回的资源过期时间（GMT 日期格式/时间戳），若用户本地时间在过期时间前，则不发送请求直接从本地获取资源。</p><h4 id="_2-2-cache-control" tabindex="-1">2.2 Cache-Control <a class="header-anchor" href="#_2-2-cache-control" aria-label="Permalink to &quot;2.2 Cache-Control&quot;">​</a></h4><ul><li>HTTP/1.1 产物。</li><li>优先级高于 Expires。</li><li>正确区分 no-cache / no-store 的作用。</li></ul><p>Cache-Control 是用于页面缓存的通用消息头字段，可以通过指定指令来实现缓存机制。</p><p>常用的字段有：</p><ul><li>max-age 设置缓存存储的最大时长，单位秒。</li><li>s-max-age 与 max-age 用法一致，不过仅适用于代理服务器。</li><li>public 表示响应可被任何对象缓存。</li><li>private 表示响应只可被私有用户缓存，不能被代理服务器缓存。</li><li>no-cache 强制客户端向服务器发起请求（禁用强缓存，可用协商缓存）。</li><li>no-store 禁止一切缓存，包含协商缓存也不可用。</li><li>must-revalidate 一旦资源过期，在成功向原始服务器验证之前，缓存不能用该资源响应后续请求。</li><li>immutable 表示响应正文不会随时间改变（只要资源不过期就不发送请求）。</li></ul><p>值得注意的是，虽然以上常用字段都是响应头的字段，但是 Cache-Control 同时也支持请求头，例如 <code>Cache-Control: max-stale=&lt;seconds&gt;</code> 表明客户端愿意接收一个已经过期但不能超出<code>&lt;seconds&gt;</code>秒的资源。</p><h4 id="_2-3-拓展知识-冷门考点" tabindex="-1">2.3 拓展知识（冷门考点） <a class="header-anchor" href="#_2-3-拓展知识-冷门考点" aria-label="Permalink to &quot;2.3 拓展知识（冷门考点）&quot;">​</a></h4><ul><li>HTTP/1.0 Pragma <ul><li>在 HTTP/1.0 时期用于禁用浏览器缓存 Pragma: no-cache。</li></ul></li><li>缓存位置 <ul><li>从 Service Worker 中读取缓存（只支持 HTTPS）。</li><li>从内存读取缓存时 network 显示 memory cache。</li><li>从硬盘读取缓存时 network 显示 disk cache。</li><li>Push Cache（推送缓存）（HTTP/2.0）。</li><li>优先级 Service Worker &gt; memory cache &gt; disk cache &gt; Push Cache。</li></ul></li><li>最佳实践：资源尽可能命中强缓存，且在资源文件更新时保证用户使用到最新的资源文件 <ul><li>强缓存只会命中相同命名的资源文件。</li><li>在资源文件上加 hash 标识（webpack 可在打包时在文件名上带上）。</li><li>通过更新资源文件名来强制更新命中强缓存的资源。</li></ul></li></ul><h3 id="_3-协商缓存" tabindex="-1">3. 协商缓存 <a class="header-anchor" href="#_3-协商缓存" aria-label="Permalink to &quot;3. 协商缓存&quot;">​</a></h3><h4 id="_3-1-etag-if-none-match" tabindex="-1">3.1 ETag / If-None-Match <a class="header-anchor" href="#_3-1-etag-if-none-match" aria-label="Permalink to &quot;3.1 ETag / If-None-Match&quot;">​</a></h4><ul><li>通过唯一标识来验证缓存。</li><li>优先级高于 Last-Modified / If-Modified-Since。</li></ul><p>如果资源请求的响应头里含有 ETag，客户端可以在后续的请求的头中带上 If-None-Match 头来验证缓存。若服务器判断资源标识一致，则返回 304 状态码告知浏览器可从本地读取缓存。</p><p>唯一标识内容是由服务端生成算法决定的，可以是资源内容生成的哈希值，也可以是最后修改时间戳的哈希值。所以 Etag 标识改变并不代表资源文件改变，反之亦然。</p><h4 id="_3-2-last-modified-if-modified-since" tabindex="-1">3.2 Last-Modified / If-Modified-Since <a class="header-anchor" href="#_3-2-last-modified-if-modified-since" aria-label="Permalink to &quot;3.2 Last-Modified / If-Modified-Since&quot;">​</a></h4><ul><li>通过资源的最后修改时间来验证缓存。</li><li>优先级低于 ETag / If-None-Match。</li><li>缺点：只能精确到秒，若 1s 内多次修改资源 Last-Modified 不会变化。</li></ul><p>如果资源请求的响应头里含有 Last-Modified，客户端可以在后续的请求的头中带上 If-Modified-Since 头来验证缓存。若服务器判断资源最后修改时间一致，则返回 304 状态码告知浏览器可从本地读取缓存。</p><h4 id="_3-3-拓展知识-冷门考点" tabindex="-1">3.3 拓展知识（冷门考点） <a class="header-anchor" href="#_3-3-拓展知识-冷门考点" aria-label="Permalink to &quot;3.3 拓展知识（冷门考点）&quot;">​</a></h4><ul><li>ETag 在标识前面加 W/ 前缀表示用弱比较算法（If-None-Match 本身就只用弱比较算法）。</li><li>ETag 还可以配合 If-Match 检测当前请求是否为最新版本，若资源不匹配返回状态码 412 错误（If-Match 不加 W/ 时使用强比较算法）。</li></ul><h3 id="_4-缓存的优缺点" tabindex="-1">4. 缓存的优缺点 <a class="header-anchor" href="#_4-缓存的优缺点" aria-label="Permalink to &quot;4. 缓存的优缺点&quot;">​</a></h3><p>优点</p><ul><li>节省了不必要的数据传输，节省带宽。</li><li>减少服务端的负担，提高网站性能。</li><li>降低网络延迟，加快页面响应速度，增强用户体验。</li></ul><p>缺点</p><ul><li>不恰当的缓存设置可能会导致资源更新不及时，导致用户获取信息滞后。</li></ul><h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考&quot;">​</a></h2><p><a href="https://developer.mozilla.org/zh-CN/docs/Web/HTTP/Caching" target="_blank" rel="noreferrer">HTTP 缓存</a></p>',40)]))}const m=e(r,[["render",h]]);export{f as __pageData,m as default};
